func (q *Queries) ListPendingGuardianAuthorityRequests(ctx context.Context, arg ListPendingGuardianAuthorityRequestsParams) ([]ListPendingGuardianAuthorityRequestsRow, error) {
	rows, err := q.db.Query(ctx, listPendingGuardianAuthorityRequests, arg.ActorID, arg.RowOffset, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListPendingGuardianAuthorityRequestsRow{}
	for rows.Next() {
		var i ListPendingGuardianAuthorityRequestsRow
		if err := rows.Scan(
			&i.RelationshipRef,
			&i.GuardianUserID,
			&i.GuardianName,
			&i.SubjectUserID,
			&i.SubjectName,
			&i.DateOfBirth,
			&i.State,
			&i.Version,
			&i.CreatedAt,
			&i.DecidingAdminUserID,
			&i.EvidenceCategory,
			&i.ReasonCode,
			&i.DecisionAt,
			&i.VerifiedUntil,
			&i.ReviewDueAt,
			&i.Conflict,
			&i.ConflictActorRef,
			&i.RenewalRef,
			&i.RenewalResponse,
			&i.RenewalStatus,
			&i.RenewalExpiryAnchor,
			&i.PersonalInvolvement,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

